    queued_overnight INTEGER NOT NULL DEFAULT 0,
    error TEXT, started_at INTEGER, finished_at INTEGER, created_at INTEGER NOT NULL
  );

CREATE INDEX IF NOT EXISTS jobs_by_user ON jobs(user_id, created_at);

