    weight REAL NOT NULL DEFAULT 1,
    text TEXT
  );

CREATE INDEX IF NOT EXISTS scout_crowd_by_source ON scout_crowd(source_id, lag_corrected_t_s);

CREATE TABLE IF NOT EXISTS scout_missions (
    id TEXT PRIMARY KEY,
